150			if v := find.Offset; v != nil {
151				query += fmt.Sprintf(" OFFSET %d", *v)
152			}
153		}
154		rows, err := d.db.QueryContext(ctx, query, args...)
155		if err != nil {
156			return nil, err
157		}
158		defer rows.Close()
159	
160		list := make([]*store.User, 0)
161		for rows.Next() {
