166				&user.Role,
167				&user.Email,
168				&user.Nickname,
169				&user.PasswordHash,
170				&user.AvatarURL,
171				&user.Description,
172				&user.CreatedTs,
173				&user.UpdatedTs,
174				&user.RowStatus,
175			); err != nil {
176				return nil, err
177			}
178			list = append(list, &user)
179		}
180	
181		if err := rows.Err(); err != nil {
182			return nil, err
183		}
184	
185		return list, nil
186	}
