188	func (d *DB) GetUser(ctx context.Context, find *store.FindUser) (*store.User, error) {
189		list, err := d.ListUsers(ctx, find)
190		if err != nil {
191			return nil, err
192		}
193		if len(list) != 1 {
194			return nil, errors.Errorf("unexpected user count: %d", len(list))
195		}
196		return list[0], nil
197	}
